// Parse agent management request
const request = $input.first().json;

// Required fields validation
if (!request.action || !request.agent_data) {
  return [{
    json: {
      error: 'Missing required fields: action, agent_data',
      status: 'invalid'
    }
  }];
}

// Create management session
const sessionId = `mgmt_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const managementRequest = {
  ...request,
  session_id: sessionId,
  timestamp: new Date().toISOString(),
  processed_by: 'agent_registration_manager'
};

return [{
  json: managementRequest
}];

// Process agent registration
const request = $input.first().json;
const agentData = request.agent_data;

// Validate required registration fields
const requiredFields = ['agent_id', 'agent_type', 'capabilities', 'communication_endpoint'];
const missingFields = requiredFields.filter(field => !agentData[field]);

if (missingFields.length > 0) {
  return [{
    json: {
      error: `Missing required registration fields: ${missingFields.join(', ')}`,
      status: 'validation_failed'
    }
  }];
}

// Create agent profile
const agentProfile = {
  agent_id: agentData.agent_id,
  agent_type: agentData.agent_type,
  display_name: agentData.display_name || agentData.agent_id,
  description: agentData.description || '',
  capabilities: agentData.capabilities,
  communication_endpoint: agentData.communication_endpoint,
  status: 'registering',
  registration_date: new Date().toISOString(),
  last_active: new Date().toISOString(),
  preferences: {
    communication_style: agentData.communication_style || 'formal',
    response_time_target: agentData.response_time_target || 30,
    collaboration_preference: agentData.collaboration_preference || 'active',
    notification_level: agentData.notification_level || 'normal'
  },
  permissions: {
    can_initiate_coordination: agentData.permissions?.can_initiate_coordination !== false,
    can_vote: agentData.permissions?.can_vote !== false,
    can_propose_actions: agentData.permissions?.can_propose_actions !== false,
    can_access_shared_context: agentData.permissions?.can_access_shared_context !== false
  },
  metadata: {
    version: '1.0.0',
    registration_source: request.registration_source || 'direct',
    approved_by: null,
    approval_date: null
  }
};

return [{
  json: {
    action: 'agent_registered',
    session_id: request.session_id,
    agent_profile: agentProfile,
    next_steps: ['Validate communication endpoint', 'Test agent connectivity', 'Grant initial permissions']
  }
}];

// Process agent status update
const request = $input.first().json;
const agentData = request.agent_data;

const statusUpdate = {
  agent_id: agentData.agent_id,
  new_status: agentData.status,
  previous_status: agentData.previous_status || 'unknown',
  status_reason: agentData.status_reason || 'Status update requested',
  timestamp: new Date().toISOString(),
  updated_by: request.updated_by || 'self',
  additional_info: agentData.additional_info || {}
};

return [{
  json: {
    action: 'status_updated',
    session_id: request.session_id,
    status_update: statusUpdate
  }
}];

// Process agent capabilities update
const request = $input.first().json;
const agentData = request.agent_data;

const capabilitiesUpdate = {
  agent_id: agentData.agent_id,
  capabilities: {
    core: agentData.capabilities?.core || [],
    specialized: agentData.capabilities?.specialized || [],
    communication: agentData.capabilities?.communication || [],
    coordination: agentData.capabilities?.coordination || []
  },
  version: agentData.capabilities_version || '1.0.0',
  updated_at: new Date().toISOString(),
  compatibility_notes: agentData.compatibility_notes || []
};

return [{
  json: {
    action: 'capabilities_updated',
    session_id: request.session_id,
    capabilities_update: capabilitiesUpdate
  }
}];

// Validate agent communication endpoint
const profile = $input.first().json;
const agentProfile = profile.agent_profile;

if (!agentProfile) {
  return [{
    json: {
      error: 'No agent profile available for validation',
      status: 'validation_failed'
    }
  }];
}

// Create validation request
const validationRequest = {
  target_endpoint: agentProfile.communication_endpoint,
  agent_id: agentProfile.agent_id,
  validation_type: 'connectivity_test',
  timeout_seconds: 10,
  test_payload: {
    type: 'ping',
    timestamp: new Date().toISOString(),
    request_id: `validation_${Date.now()}`
  }
};

return [{
  json: {
    action: 'validate_endpoint',
    session_id: profile.session_id,
    validation_request: validationRequest,
    agent_profile: agentProfile
  }
}];

// Process validation result and complete registration
const validation = $input.first().json;
const originalData = $('Validate Agent Endpoint').first().json;

let registrationStatus;
let activationSteps = [];

if (validation.status >= 200 && validation.status < 300) {
  // Successful validation
  registrationStatus = 'active';
  activationSteps = [
    'Endpoint validation successful',
    'Agent communication verified',
    'Granting system access',
    'Notifying other agents'
  ];
} else {
  // Validation failed
  registrationStatus = 'registration_failed';
  activationSteps = [
    'Endpoint validation failed',
    'Please check communication endpoint',
    'Registration will remain pending'
  ];
}

const completedRegistration = {
  ...originalData.agent_profile,
  status: registrationStatus,
  validation_result: {
    status_code: validation.status,
    response_time: validation.responseTime || 'unknown',
    validated_at: new Date().toISOString(),
    success: registrationStatus === 'active'
  },
  activation_steps: activationSteps,
  completed_at: new Date().toISOString()
};

return [{
  json: {
    action: 'registration_completed',
    session_id: originalData.session_id,
    registration_result: completedRegistration
  }
}];

// Notify other agents about new registration
const registration = $input.first().json;
const agentProfile = registration.registration_result;

if (agentProfile.status !== 'active') {
  return [{
    json: {
      action: 'skip_notification',
      reason: 'Agent not successfully activated'
    }
  }];
}

const notification = {
  type: 'agent_registered_notification',
  from_agent: 'agent_registration_manager',
  broadcast_to: 'all_active_agents',
  data: {
    new_agent: {
      agent_id: agentProfile.agent_id,
      display_name: agentProfile.display_name,
      agent_type: agentProfile.agent_type,
      capabilities: agentProfile.capabilities,
      registered_at: agentProfile.registration_date
    },
    message: `New agent registered: ${agentProfile.display_name} (${agentProfile.agent_type})\n\nCapabilities: ${agentProfile.capabilities.join(', ')}\n\nAgent is now active and available for coordination.`
  }
};

return [{
  json: notification
}];
